/* @author MILO-GAO(高振銘)@2020 */ package page2020.client;import org.springframework.util.StringUtils;import page2020.core.Name;public class ClientConfig extends Name<ClientConfig> {	private boolean active;	private String green;	private String client;	private String passport;	private String host;	private String sysCode;	private String username;	private String password;	private String csrf;	public ClientConfig(String setting) {		super();		String[] tokens = StringUtils.trimAllWhitespace(setting).split(";");		this.active = tokens[0].equals("0") ? false : true;		if (this.active) { 			super.name(tokens[1]);			this.client = tokens[2];			this.green = tokens[3];			this.host = tokens[4];			if (tokens.length > 5) {				this.sysCode = tokens[5];				this.username = tokens[6];				this.password = tokens[7];			}		}	}	public static String passKey(String username, String green) {		return String.format("%s/%s/%s", username, green, "P@s$W0&d#2021#11!!");	}	public String passKey() {		return String.format("%s/%s/%s", this.client, this.green, "P@s$W0&d#2021#11!!");	}	@Override	public String toString() {		return "ClientConfig [active=" + active + ", green=" + green + ", client=" + client + ", host=" + host				+ ", sysCode=" + sysCode + ", username=" + username + ", csrf=" + csrf + "]";	}	public boolean isActive() {		return active;	}	public void setActive(boolean active) {		this.active = active;	}	public String getGreen() {		return green;	}	public void setGreen(String green) {		this.green = green;	}	public String getClient() {		return client;	}	public void setClient(String client) {		this.client = client;	}	public String getPassport() {		return passport;	}	public void setPassport(String passport) {		this.passport = passport;	}	public String getHost() {		return host;	}	public void setHost(String host) {		this.host = host;	}	public String getSysCode() {		return sysCode;	}	public void setSysCode(String sysCode) {		this.sysCode = sysCode;	}	public String getUsername() {		return username;	}	public void setUsername(String username) {		this.username = username;	}	public String getPassword() {		return password;	}	public void setPassword(String password) {		this.password = password;	}	public String getCsrf() {		return csrf;	}	public void setCsrf(String csrf) {		this.csrf = csrf;	}}